import json

# Load and validate output
with open('/app/data/output.json', 'r') as f:
    content = f.read()

# Check trailing newline
if not content.endswith('\n'):
    print('ERROR: No trailing newline')
elif content.endswith('\n\n'):
    print('ERROR: Multiple trailing newlines')
else:
    print('OK: Single trailing newline')

# Parse JSON
data = json.loads(content)

# Check top-level keys
expected_keys = {'feature_importance', 'model_performance', 'predictions'}
actual_keys = set(data.keys())
if actual_keys != expected_keys:
    print(f'ERROR: Wrong top-level keys. Expected {expected_keys}, got {actual_keys}')
else:
    print('OK: Top-level keys correct')

# Check predictions count
num_predictions = len(data['predictions'])
print(f'OK: {num_predictions} predictions (expected 24)')

# Check predictions are sorted by sample_id
sample_ids = [p['sample_id'] for p in data['predictions']]
if sample_ids == sorted(sample_ids):
    print('OK: Predictions sorted by sample_id')
else:
    print('ERROR: Predictions not sorted')

# Check each prediction has required keys
required_pred_keys = {'sample_id', 'predicted_state', 'confidence_score', 'state_match_score', 'feature_contributions', 'anomaly_indicators'}
for i, pred in enumerate(data['predictions']):
    if set(pred.keys()) != required_pred_keys:
        print(f'ERROR: Prediction {i} has wrong keys: {set(pred.keys())}')
        break
else:
    print('OK: All predictions have correct keys')

# Check feature_contributions has 8 sensors
required_sensors = {'motor_temperature_c', 'vibration_amplitude_mm', 'current_consumption_a', 'position_error_mm', 'velocity_rpm', 'torque_nm', 'encoder_reading', 'operational_hours'}
for i, pred in enumerate(data['predictions']):
    fc = pred['feature_contributions']
    if set(fc.keys()) != required_sensors:
        print(f'ERROR: Prediction {i} feature_contributions has wrong sensors: {set(fc.keys())}')
        break
else:
    print('OK: All feature_contributions have correct sensors')

# Check feature_importance
if len(data['feature_importance']) != 8:
    print(f'ERROR: feature_importance has {len(data[\"feature_importance\"])} entries, expected 8')
else:
    print('OK: feature_importance has 8 entries')

fi_keys = set()
for fi in data['feature_importance']:
    if set(fi.keys()) != {'feature', 'importance'}:
        print(f'ERROR: feature_importance entry has wrong keys: {set(fi.keys())}')
        break
    fi_keys.add(fi['feature'])
if fi_keys == required_sensors:
    print('OK: feature_importance has all 8 sensors')
else:
    print(f'ERROR: feature_importance missing sensors: {required_sensors - fi_keys}')

# Check model_performance
mp = data['model_performance']
required_mp_keys = {'accuracy', 'precision', 'recall', 'f1_score', 'confusion_matrix'}
if set(mp.keys()) != required_mp_keys:
    print(f'ERROR: model_performance has wrong keys: {set(mp.keys())}')
else:
    print('OK: model_performance has correct keys')

# Check confusion_matrix
cm = mp['confusion_matrix']
if set(cm.keys()) != {'critical', 'degraded', 'normal', 'warning'}:
    print(f'ERROR: confusion_matrix outer keys wrong: {set(cm.keys())}')
else:
    print('OK: confusion_matrix has correct outer keys')

for state, inner in cm.items():
    if set(inner.keys()) != {'critical', 'degraded', 'normal', 'warning'}:
        print(f'ERROR: confusion_matrix inner keys for {state} wrong: {set(inner.keys())}')
    # Check all values are non-negative integers
    for k, v in inner.items():
        if not isinstance(v, int) or v < 0:
            print(f'ERROR: confusion_matrix[{state}][{k}] = {v} is not a non-negative integer')
print('OK: confusion_matrix structure valid')

print('\\nAll validation checks passed!')
